/**
 * Merge each course's enrichment sections onto its base record. The single call
 * site both content sources (`local.ts`'s fixtures and `cms/store.ts`'s seed) must
 * use — duplicating this merge inline let it drift once already (`local.ts` shipped
 * without it, so every production course page silently rendered without curriculum,
 * highlights, tools, career roles, hiring partners, or FAQs).
 */
export function withCourseSections(items: Course[]): Course[] {
  return items.map((c) => ({ ...c, ...(courseSections[c.slug] ?? {}) }));
}
